function checkHookHandler(file, event, spec, hook) {
  const where = `${event} hook`;
  if (hook.type !== 'command') add('ERROR', file, `${where}: type must be "command".`);
  if (hook.command !== 'node') add('ERROR', file, `${where}: use exec form — command "node" with the script in args (found command ${JSON.stringify(hook.command)}).`);
  const script = hookScript(hook);
  if (!script) {
    add('ERROR', file, `${where}: args must be exactly ["\${CLAUDE_PROJECT_DIR}/.claude/hooks/<script>.js"] (found ${JSON.stringify(hook.args)}).`);
  } else if (!common.exists(script)) {
    add('ERROR', file, `${where}: script missing: ${script}`);
  }
  if (spec.failClosed && hook.onFailure !== 'block') {
    add('ERROR', file, `${where}: critical pre-tool enforcement must fail closed (onFailure: "block").`);
  }
  if (!spec.failClosed && hook.onFailure !== undefined) {
    add('ERROR', file, `${where}: onFailure is reserved for the critical PreToolUse enforcement; post-change and Stop hooks report failures visibly without blocking (on Stop it has no effect).`);
  }
}

const CHECKED = /#\s*add-dependency:\s*checked\b/i;
const PEER_OVERRIDE = /#\s*peer-override:\s*approved-by-user\b/i;
const REFERENCE_CHECKED = /#\s*project-reference:\s*checked\b/i;

const FORCE_OPTIONS = new Set(['--force', '-f', '--legacy-peer-deps']);
const FORCE_MANAGERS = new Set(['npm', 'pnpm', 'yarn']);

function forceFlag(op) {
  if (op.type !== 'package' || !FORCE_MANAGERS.has(op.manager)) return null;
  return op.options.find((o) => FORCE_OPTIONS.has(o) && (o !== '-f' || op.manager === 'npm')) || null;
}

function versionNotes(op) {
  const notes = [];
  const text = [...op.packages, ...op.options].join(' ');
  if (op.options.includes('--prerelease') || /@(?:next|canary|beta|alpha|rc)\b/i.test(text)) notes.push('The command requests a prerelease version.');
  if (/--version=["']?\*|@\*(?:\s|$)|@latest\b/i.test(text) || (op.options.includes('--version') && /(?:^|\s)\*(?:\s|$)/.test(op.text))) {
    notes.push('The command requests a floating or unresolved version.');
  }
  return notes;
}

function describe(op) {
  if (op.type === 'reference') return `project reference ${op.verb}`;
  const what = op.manager === 'dotnet' || op.manager === 'nuget' ? 'NuGet package' : op.manager === 'ng' ? 'frontend package' : `${op.manager} package`;
  return `${what} ${op.addition ? 'addition' : 'change'}`;
}

// Returns { block: boolean, message?: string }.
function analyzeCommand(command, shell) {
  const ops = classifyCommand(command, shell);
  for (const op of ops) {
    const flag = forceFlag(op);
    if (flag && !PEER_OVERRIDE.test(op.comment)) {
      return {
        block: true,
        message:
          `Peer-dependency override flag detected (${flag}) in: ${op.text}\n` +
          `Resolve the actual compatibility problem instead (${DEPENDENCY_WORKFLOW}, Install).\n` +
          'Only when the user explicitly approved the override, re-run the same command with the trailing comment: # peer-override: approved-by-user\n',
      };
    }
  }
  const references = ops.filter((op) => op.type === 'reference' && !REFERENCE_CHECKED.test(op.comment));

// PreToolUse: an internal failure denies the tool call instead of silently allowing it.
function denyOnFailure(hookName, error, consequence) {
  denyToolUse(
    `${hookName} hook failed (${errorText(error)}); ${consequence}, so the command was blocked.\n` +
      'Report the hook failure to the user; the instruction system is repaired through the template-maintenance workflow.\n'
  );
}

